#!/bin/bash
# Reference solution (oracle) for irssi-arvo-31491-e2e, generated by conversion/convert.py.
# Writes the upstream fix (projects/irssi/arvo_31491/patch.diff @ 8365b29) to
# /output/fix.patch and the ground-truth PoC to /output/poc.bin.
set -euo pipefail

mkdir -p /output
base64 -d > /output/fix.patch <<'B64'
